import sys
from collections import Counter

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    words = line.split()
    counts = Counter(words)
    sorted_items = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    for word, freq in sorted_items:
        print(f"{word} {freq}")

if __name__ == "__main__":
    main()
